//! media.library's functions: container files - MP4 - opened, their
//! tracks listed, and each track's packets handed out as they are coded,
//! for a decoder. Open it with OpenLibrary("media.library", 1); the
//! structures are in sdk.media.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/media_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const media = @import("../libs/media/media.zig");
const utility = @import("../libs/utility/utility.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "media.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const OpenMedia = libraries.lvo(4);
    pub const CloseMedia = libraries.lvo(5);
    pub const GetMediaInfo = libraries.lvo(6);
    pub const GetMediaTrack = libraries.lvo(7);
    pub const ReadMediaPacket = libraries.lvo(8);
    pub const SeekMedia = libraries.lvo(9);
    pub const IdentifyMedia = libraries.lvo(10);
    pub const MediaErrorText = libraries.lvo(11);
    pub const GetMediaAttrs = libraries.lvo(12);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const OpenMedia = *const fn (*MediaBase, ?[*]const utility.TagItem, ?*i32) callconv(.c) ?*media.MediaFile;
    pub const CloseMedia = *const fn (*MediaBase, ?*media.MediaFile) callconv(.c) void;
    pub const GetMediaInfo = *const fn (*MediaBase, *media.MediaFile, *media.MediaInfo) callconv(.c) void;
    pub const GetMediaTrack = *const fn (*MediaBase, *media.MediaFile, u32, *media.MediaTrack) callconv(.c) i32;
    pub const ReadMediaPacket = *const fn (*MediaBase, *media.MediaFile, u32, *media.MediaPacket) callconv(.c) i32;
    pub const SeekMedia = *const fn (*MediaBase, *media.MediaFile, u32, i64) callconv(.c) i32;
    pub const IdentifyMedia = *const fn (*MediaBase, [*]const u8, u32) callconv(.c) u32;
    pub const MediaErrorText = *const fn (*MediaBase, i32) callconv(.c) [*:0]const u8;
    pub const GetMediaAttrs = *const fn (*MediaBase, *media.MediaFile, ?[*]const utility.TagItem) callconv(.c) u32;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const MediaBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *MediaBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// A file, a file handle or a read function opened, its kind found by its
    /// first bytes. Null, and why in `err` (MERR_*), when it failed.
    pub fn OpenMedia(self: *MediaBase, tags: ?[*]const utility.TagItem, err: ?*i32) ?*media.MediaFile {
        return libraries.call(self, LVO.OpenMedia, Fn.OpenMedia, .{ tags, err });
    }

    /// The file closed and freed, with the file it opened.
    pub fn CloseMedia(self: *MediaBase, file: ?*media.MediaFile) void {
        return libraries.call(self, LVO.CloseMedia, Fn.CloseMedia, .{file});
    }

    /// What the file is: its kind, its tracks, its length, its names.
    pub fn GetMediaInfo(self: *MediaBase, file: *media.MediaFile, info: *media.MediaInfo) void {
        return libraries.call(self, LVO.GetMediaInfo, Fn.GetMediaInfo, .{ file, info });
    }

    /// What track `track` is: 0, or MERR_NOTRACK.
    pub fn GetMediaTrack(self: *MediaBase, file: *media.MediaFile, track: u32, info: *media.MediaTrack) i32 {
        return libraries.call(self, LVO.GetMediaTrack, Fn.GetMediaTrack, .{ file, track, info });
    }

    /// Track `track`'s next packet into `packet`: 0, MERR_END after its last,
    /// or an MERR_*.
    pub fn ReadMediaPacket(self: *MediaBase, file: *media.MediaFile, track: u32, packet: *media.MediaPacket) i32 {
        return libraries.call(self, LVO.ReadMediaPacket, Fn.ReadMediaPacket, .{ file, track, packet });
    }

    /// Track `track` moved to the packet a decoder can start at, at or before
    /// `time` microseconds: 0, or an MERR_*.
    pub fn SeekMedia(self: *MediaBase, file: *media.MediaFile, track: u32, time: i64) i32 {
        return libraries.call(self, LVO.SeekMedia, Fn.SeekMedia, .{ file, track, time });
    }

    /// The kind (MEDIA_*) the first bytes of a file are.
    pub fn IdentifyMedia(self: *MediaBase, bytes: [*]const u8, length: u32) u32 {
        return libraries.call(self, LVO.IdentifyMedia, Fn.IdentifyMedia, .{ bytes, length });
    }

    /// What an error code means, in words.
    pub fn MediaErrorText(self: *MediaBase, code: i32) [*:0]const u8 {
        return libraries.call(self, LVO.MediaErrorText, Fn.MediaErrorText, .{code});
    }

    /// The file's tags, each into where its data points: how many of them
    /// were answered.
    pub fn GetMediaAttrs(self: *MediaBase, file: *media.MediaFile, tags: ?[*]const utility.TagItem) u32 {
        return libraries.call(self, LVO.GetMediaAttrs, Fn.GetMediaAttrs, .{ file, tags });
    }
};
